5	namespace AtrioTeam\DigitalHub\Assets\Console;
6	
7	use AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob;
8	use Illuminate\Console\Command;
9	use Illuminate\Database\Eloquent\Collection as EloquentCollection;
10	use Spatie\MediaLibrary\MediaCollections\Models\Media;
11	
12	/**
13	 * Rilancia {@see ProcessAssetJob} (metadati, dimensioni, poster/thumbnail) per
14	 * uno o tutti gli asset. Utile per il backfill su media caricati prima della
15	 * pipeline o dopo averla estesa (es. nuovo tipo di anteprima).
16	 *
17	 * Il job viene accodato (sulla coda `assets`): con `QUEUE_CONNECTION=sync` gira
18	 * inline qui nel comando, altrimenti lo elaborerà il worker.
19	 */
20	class ReprocessAssetsCommand extends Command
21	{
22	    protected $signature = 'digital-hub:reprocess-assets
23	        {media? : ID del media da riprocessare (se omesso: tutti gli asset)}
24	        {--collection=assets : Media collection da riprocessare quando non si passa un ID}';
25	
26	    protected $description = 'Rilancia l\'elaborazione (metadati, dimensioni, poster) di uno o tutti gli asset';
27	
28	    public function handle(): int
29	    {
30	        $media = $this->argument('media');
31	
32	        return $media !== null
33	            ? $this->reprocessOne($media)
34	            : $this->reprocessAll((string) $this->option('collection'));
35	    }
36	
37	    private function reprocessOne(string $id): int
38	    {
39	        if (! is_numeric($id)) {
40	            $this->error("ID media non valido: {$id}");
41	
42	            return self::FAILURE;
43	        }
44	
45	        $media = Media::query()->whereKey((int) $id)->first();
46	        if (! $media instanceof Media) {
47	            $this->error("Media #{$id} non trovato.");
48	
49	            return self::FAILURE;
50	        }
51	
52	        ProcessAssetJob::dispatch((int) $id);
53	        $this->info("Riprocesso accodato per il media #{$id} ({$media->file_name}).");
54	
55	        return self::SUCCESS;
56	    }
57	
58	    private function reprocessAll(string $collection): int
59	    {
60	        $query = Media::query()->where('collection_name', $collection);
61	        $total = $query->count();
62	
63	        if ($total === 0) {
64	            $this->warn("Nessun asset nella collection '{$collection}'.");
65	
66	            return self::SUCCESS;
67	        }
68	
69	        $this->info("Accodo il riprocesso di {$total} asset (collection '{$collection}')…");
70	        $bar = $this->output->createProgressBar($total);
71	        $bar->start();
72	
73	        $query->chunkById(200, function (EloquentCollection $rows) use ($bar): void {
74	            foreach ($rows as $media) {
75	                $key = $media->getKey();
76	                if (is_int($key) || is_string($key)) {
77	                    ProcessAssetJob::dispatch((int) $key);
78	                }
79	                $bar->advance();
80	            }
81	        });
82	
83	        $bar->finish();
84	        $this->newLine(2);
85	        $this->info('Fatto.');
86	
87	        return self::SUCCESS;
88	    }
89	}
