5	namespace Tests\Feature\Api;
6	
7	use App\Models\Product;
8	use AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob;
9	use AtrioTeam\DigitalHub\Assets\Metadata\MetadataExtractionPipeline;
10	use AtrioTeam\DigitalHub\Assets\Models\AssetFolder;
11	use AtrioTeam\DigitalHub\Assets\Support\AssetHash;
12	use AtrioTeam\DigitalHub\Assets\Support\AssetPublication;
13	use Illuminate\Foundation\Testing\RefreshDatabase;
14	use Illuminate\Support\Facades\Storage;
15	use Spatie\MediaLibrary\MediaCollections\Models\Media;
16	use Tests\TestCase;
17	
18	/**
19	 * Lettura degli asset dall'API esterna (roadmap #24): è ciò che alimenta il
20	 * media manager del CMS a valle, da cui parte la scelta del file e quindi la
21	 * pubblicazione (#34).
22	 */
23	class AssetApiTest extends TestCase
24	{
25	    use RefreshDatabase;
26	
27	    private const TOKEN = 'token-cms';
28	
29	    private const CONSUMER = 'atmosphera-admin';
30	
31	    protected function setUp(): void
32	    {
33	        parent::setUp();
34	
35	        config(['digital-hub.api.tokens' => self::CONSUMER . ':' . self::TOKEN]);
36	        Storage::fake('assets');
37	    }
38	
39	    public function test_it_rejects_a_request_without_a_valid_token(): void
40	    {
41	        $this->getJson('/api/v1/assets')->assertUnauthorized();
42	    }
43	
44	    public function test_it_lists_the_assets(): void
45	    {
46	        $product = $this->product('Tavolo');
47	        $this->attachImage($product, 'photo.jpg');
48	        $this->attachImage($product, 'render.jpg');
49	
50	        $this->withToken(self::TOKEN)
51	            ->getJson('/api/v1/assets')
52	            ->assertOk()
53	            ->assertJsonCount(2, 'data')
54	            ->assertJsonPath('data.0.file_name', 'photo.jpg')
55	            ->assertJsonPath('data.0.owner.global_id', $product->global_id);
56	    }
57	
58	    /**
59	     * L'endpoint espone gli asset, non tutta la tabella `media`: un media di
60	     * un'altra collection non deve uscire per il solo fatto di stare lì.
61	     */
62	    public function test_it_only_exposes_the_declared_asset_collections(): void
63	    {
64	        $product = $this->product('Tavolo');
65	        $this->attachImage($product, 'photo.jpg');
66	        $product->addMediaFromString($this->jpeg())->usingFileName('avatar.jpg')->toMediaCollection('other', 'assets');
67	
68	        $this->withToken(self::TOKEN)
69	            ->getJson('/api/v1/assets')
70	            ->assertOk()
71	            ->assertJsonCount(1, 'data')
72	            ->assertJsonPath('data.0.file_name', 'photo.jpg');
73	    }
74	
75	    /**
76	     * Il payload deve bastare a mostrare l'asset nel picker senza una seconda
77	     * richiesta per file.
78	     */
79	    public function test_the_payload_carries_what_the_media_manager_needs(): void
80	    {
81	        $product = $this->product('Tavolo');
82	        $folder = AssetFolder::create([
83	            'folderable_type' => $product->getMorphClass(),
84	            'folderable_id' => $product->getKey(),
85	            'name' => 'Schede tecniche',
86	        ]);
87	
88	        $media = $this->attachImage($product, 'photo.jpg');
89	        $media->forceFill(['asset_folder_id' => $folder->getKey()])->save();
90	
91	        $this->withToken(self::TOKEN)
92	            ->getJson('/api/v1/assets/' . $media->global_id)
93	            ->assertOk()
94	            ->assertJsonPath('data.global_id', $media->global_id)
95	            ->assertJsonPath('data.mime_type', 'image/jpeg')
96	            ->assertJsonPath('data.folder.name', 'Schede tecniche')
97	            ->assertJsonPath('data.owner.global_id', $product->global_id)
98	            ->assertJsonStructure(['data' => [
99	                'size', 'file_hash', 'metadata', 'preview_url', 'download_url',
100	                'temporary_urls_expire_at', 'public_url', 'updated_at',
101	            ]]);
102	    }
103	
104	    /**
105	     * Gli URL temporanei sono la sola via d'accesso al file da fuori sessione
106	     * finché l'asset non è pubblicato: se non funzionassero, il picker del CMS
107	     * mostrerebbe immagini rotte.
108	     */
109	    public function test_the_temporary_download_url_works_without_a_session(): void
110	    {
111	        $media = $this->attachImage($this->product('Tavolo'), 'photo.jpg');
112	
113	        $url = $this->withToken(self::TOKEN)
114	            ->getJson('/api/v1/assets/' . $media->global_id)
115	            ->json('data.download_url');
116	
117	        $this->assertIsString($url);
118	        $this->get($url)->assertOk();
119	    }
120	
121	    /**
122	     * `public_url` resta null finché l'asset non è pubblicato: questo endpoint
123	     * non pubblica niente, la pubblicazione è la dichiarazione di un utilizzo
124	     * (#34).
125	     */
126	    public function test_the_public_url_is_null_until_the_asset_is_published(): void
127	    {
128	        $media = $this->attachImage($this->product('Tavolo'), 'photo.jpg');
129	
130	        $this->withToken(self::TOKEN)
131	            ->getJson('/api/v1/assets/' . $media->global_id)
132	            ->assertJsonPath('data.public_url', null)
133	            ->assertJsonPath('data.published_at', null);
134	
135	        AssetPublication::publish($media);
136	
137	        $this->withToken(self::TOKEN)
138	            ->getJson('/api/v1/assets/' . $media->global_id)
139	            ->assertJsonPath('data.public_url', fn (?string $url): bool => is_string($url) && $url !== '');
140	    }
141	
142	    /**
143	     * L'hash è ciò che distingue "byte cambiati" da "record toccato": deve
144	     * restare identico a una rinomina e cambiare a una sostituzione del file.
145	     */
146	    public function test_the_file_hash_tracks_the_content_not_the_record(): void
147	    {
148	        $media = $this->attachImage($this->product('Tavolo'), 'photo.jpg');
149	
150	        $hash = $this->hashOf($media);
151	        $this->assertNotNull($hash);
152	
153	        $media->forceFill(['name' => 'Rinominato'])->save();
154	        $this->assertSame($hash, $this->hashOf($media));
155	
156	        Storage::disk('assets')->put($media->getPathRelativeToRoot(), 'contenuto diverso');
157	        (new ProcessAssetJob((int) $media->getKey()))->handle(app(MetadataExtractionPipeline::class));
158	
159	        $this->assertNotSame($hash, $this->hashOf($media));
160	    }
161	
162	    /** Finché il worker della coda non è passato l'hash è null, non inventato. */
163	    public function test_the_file_hash_is_null_before_processing(): void
164	    {
165	        $media = $this->attachImage($this->product('Tavolo'), 'photo.jpg', process: false);
166	
167	        $this->withToken(self::TOKEN)
168	            ->getJson('/api/v1/assets/' . $media->global_id)
169	            ->assertJsonPath('data.file_hash', null);
170	    }
171	
172	    public function test_it_filters_by_owner(): void
173	    {
174	        $tavolo = $this->product('Tavolo');
175	        $sedia = $this->product('Sedia');
176	        $this->attachImage($tavolo, 'tavolo.jpg');
177	        $this->attachImage($sedia, 'sedia.jpg');
178	
179	        $this->withToken(self::TOKEN)
180	            ->getJson('/api/v1/assets?owner=' . $sedia->global_id)
181	            ->assertOk()
182	            ->assertJsonCount(1, 'data')
183	            ->assertJsonPath('data.0.file_name', 'sedia.jpg');
184	    }
185	
186	    /**
187	     * Un owner inesistente è un errore del client, non una lista vuota: quella
188	     * si leggerebbe come "quel record non ha asset".
189	     */
190	    public function test_it_rejects_an_unknown_owner(): void
191	    {
192	        $this->withToken(self::TOKEN)
193	            ->getJson('/api/v1/assets?owner=inesistenti:1')
194	            ->assertJsonValidationErrors(['owner']);
195	    }
196	
197	    public function test_it_filters_by_mime_prefix_and_by_name(): void
198	    {
199	        $product = $this->product('Tavolo');
200	        $this->attachImage($product, 'photo.jpg');
201	        $product->addMediaFromString('%PDF-1.4')->usingFileName('scheda.pdf')->toMediaCollection('assets');
202	
203	        $this->withToken(self::TOKEN)

