{
 "info": {
  "name": "Atmosphera Hub — API esterna (#24)",
  "description": "API di sola lettura consumata in pull dai CMS a valle (il primo è atmosphera-admin).\n\nAuth: `Authorization: Bearer {{apiToken}}` — token di servizio da `DIGITAL_HUB_API_TOKENS`.\nLingua: `?locale=` (ristretta a `config('digital-hub.locales')`).\nChiave di join cross-sistema: `global_id` ({table}:{id}), non l'id locale.\n\nLa cartella \"Contratto\" contiene i casi di errore: sono parte del contratto verso il client, non scarti.\nRunnabile con Collection Runner o newman; l'ordine conta solo per la cattura di `{{globalId}}` nella prima richiesta.",
  "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json"
 },
 "auth": {
  "type": "bearer",
  "bearer": [
   {
    "key": "token",
    "value": "{{apiToken}}",
    "type": "string"
   }
  ]
 },
 "variable": [
  {
   "key": "resource",
   "value": "designers",
   "description": "Slug dichiarato in config('digital-hub.api.resources')"
  },
  {
   "key": "assetGlobalId",
   "value": "media:1",
   "description": "global_id di un asset esistente a DB (colonna media.global_id)"
  }
 ],
 "item": [
  {
   "name": "Lettura",
   "item": [
    {
     "name": "Lista designer",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "const body = pm.response.json();",
         "pm.test('ha data + meta di paginazione', () => {",
         "    pm.expect(body).to.have.property('data');",
         "    pm.expect(body.meta).to.have.property('total');",
         "});",
         "pm.test('ogni record espone il global_id come chiave di join', () => {",
         "    body.data.forEach(r => pm.expect(r.global_id, 'global_id').to.be.a('string'));",
         "});",
         "// Cattura il primo global_id per le richieste successive.",
         "if (body.data.length > 0) {",
         "    pm.collectionVariables.set('globalId', body.data[0].global_id);",
         "    pm.collectionVariables.set('recordId', String(body.data[0].global_id).split(':')[1]);",
         "} else {",
         "    console.warn('Nessun designer nel DB: le richieste per identifier daranno 404.');",
         "}"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ]
      },
      "description": "Prima pagina. `name` esce già risolto nella lingua di default dell'app, non come mappa translatable."
     }
    },
    {
     "name": "Lista in inglese (?locale=en)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('name è una stringa risolta, non una mappa lingua=>valore', () => {",
         "    const data = pm.response.json().data;",
         "    if (data.length === 0) { pm.expect.fail('Nessun designer nel DB'); }",
         "    pm.expect(data[0].name).to.satisfy(v => v === null || typeof v === 'string');",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}?locale=en",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ],
       "query": [
        {
         "key": "locale",
         "value": "en"
        }
       ]
      }
     }
    },
    {
     "name": "Singolo per global_id",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('è il record richiesto', () => {",
         "    pm.expect(pm.response.json().data.global_id).to.eql(pm.collectionVariables.get('globalId'));",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}/{{globalId}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}",
        "{{globalId}}"
       ]
      },
      "description": "I due punti del global_id ({table}:{id}) nel path sono legittimi, non vanno codificati."
     }
    },
    {
     "name": "Singolo per id numerico",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('stesso record raggiunto per global_id', () => {",
         "    pm.expect(pm.response.json().data.global_id).to.eql(pm.collectionVariables.get('globalId'));",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}/{{recordId}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}",
        "{{recordId}}"
       ]
      },
      "description": "Comodo in debug, ma il client deve usare il global_id: l'id locale dell'hub non è identità stabile per il consumatore."
     }
    }
   ]
  },
  {
   "name": "Sync",
   "item": [
    {
     "name": "Incrementale (updated_since = ieri)",
     "event": [
      {
       "listen": "prerequest",
       "script": {
        "type": "text/javascript",
        "exec": [
         "// Data mobile: la richiesta resta valida a distanza di mesi.",
         "const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);",
         "pm.collectionVariables.set('updatedSince', yesterday.toISOString());"
        ]
       }
      },
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('restituisce solo record toccati dopo la soglia', () => {",
         "    const soglia = new Date(pm.collectionVariables.get('updatedSince'));",
         "    pm.response.json().data.forEach(r => {",
         "        pm.expect(new Date(r.updated_at)).to.be.at.least(soglia);",
         "    });",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}?updated_since={{updatedSince}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ],
       "query": [
        {
         "key": "updated_since",
         "value": "{{updatedSince}}"
        }
       ]
      },
      "description": "È ciò che rende possibile il sync incrementale del CMS.\n\nAttenzione al formato: con un offset tipo +02:00 il `+` va urlencodato (%2B), altrimenti arriva come spazio e la validazione risponde 422. Postman lo codifica, curl no. La forma ISO in UTC (…Z) usata qui non ha il problema."
     }
    },
    {
     "name": "Paginazione (per_page=1)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200', () => pm.response.to.have.status(200));",
         "pm.test('rispetta per_page', () => {",
         "    pm.expect(pm.response.json().data.length).to.be.at.most(1);",
         "});",
         "pm.test('espone i link per iterare fino all\\'ultima pagina', () => {",
         "    pm.expect(pm.response.json().meta).to.have.property('last_page');",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/{{resource}}?per_page=1&page=1",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "{{resource}}"
       ],
       "query": [
        {
         "key": "per_page",
         "value": "1"
        },
        {
         "key": "page",
         "value": "1"
        }
       ]
      }
     }
    }
   ]
  },
  {
   "name": "Asset — pubblicazione e utilizzi (#34)",
   "description": "Il flusso dietro alla scelta di un asset dal media manager del CMS: il client dichiara l'utilizzo e riceve in risposta l'URL pubblico permanente del file (#33). L'entità di origine deve esistere già lato consumer: l'upsert è chiavato su source_type + source_id.",
   "item": [
    {
     "name": "Dichiara l'utilizzo (pubblica e restituisce l'URL)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('201 alla prima dichiarazione, 200 alle successive', () => pm.expect(pm.response.code).to.be.oneOf([200, 201]));",
         "const d = pm.response.json().data;",
         "pm.test('restituisce un URL pubblico', () => pm.expect(d.public_url).to.be.a('string'));",
         "pm.test('published_at valorizzato', () => pm.expect(d.published_at).to.be.a('string'));",
         "pm.test('rimanda indietro l\\'utilizzo registrato', () => {",
         "    pm.expect(d.usage.source_type).to.eql('page');",
         "    pm.expect(d.usage.source_id).to.eql('42');",
         "});",
         "pm.collectionVariables.set('publicUrl', d.public_url);"
        ]
       }
      }
     ],
     "request": {
      "method": "POST",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       },
       {
        "key": "Content-Type",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/assets/{{assetGlobalId}}/usages",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "assets",
        "{{assetGlobalId}}",
        "usages"
       ]
      },
      "description": "Idempotente: la prima chiamata pubblica l'asset (201), le successive aggiornano la riga e restituiscono lo stesso URL (200).",
      "body": {
       "mode": "raw",
       "raw": "{\n  \"source_type\": \"page\",\n  \"source_id\": \"42\",\n  \"label\": \"Scheda tecnica — Tavolo Aria\",\n  \"source_url\": \"https://atmosphera-admin.test/admin/pages/42\"\n}",
       "options": {
        "raw": {
         "language": "json"
        }
       }
      }
     }
    },
    {
     "name": "Ridichiara lo stesso utilizzo (idempotenza)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200 — riga aggiornata, non creata', () => pm.response.to.have.status(200));",
         "pm.test('URL pubblico invariato: il token non si rigenera', () => {",
         "    pm.expect(pm.response.json().data.public_url).to.eql(pm.collectionVariables.get('publicUrl'));",
         "});"
        ]
       }
      }
     ],
     "request": {
      "method": "POST",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       },
       {
        "key": "Content-Type",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{baseUrl}}/api/v1/assets/{{assetGlobalId}}/usages",
       "host": [
        "{{baseUrl}}"
       ],
       "path": [
        "api",
        "v1",
        "assets",
        "{{assetGlobalId}}",
        "usages"
       ]
      },
      "description": "Stessa origine, label aggiornata: nessuna riga nuova, stesso URL. Il CMS può chiamare a ogni salvataggio senza tenere stato.",
      "body": {
       "mode": "raw",
       "raw": "{\n  \"source_type\": \"page\",\n  \"source_id\": \"42\",\n  \"label\": \"Scheda tecnica — Tavolo Aria (rev. 2)\",\n  \"source_url\": \"https://atmosphera-admin.test/admin/pages/42\"\n}",
       "options": {
        "raw": {
         "language": "json"
        }
       }
      }
     }
    },
    {
     "name": "L'URL pubblico è servibile senza token",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200 senza autenticazione', () => pm.response.to.have.status(200));"
        ]
       }
      }
     ],
     "request": {
      "method": "GET",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
       }
      ],
      "url": {
       "raw": "{{publicUrl}}",
       "host": [
        "{{baseUrl}}"
       ],
       "path": []
      },
      "description": "Il link che il CMS mette in pagina: nessuna sessione, nessun Bearer.",
      "auth": {
       "type": "noauth"
      }
     }
    },
    {
     "name": "Ritira l'utilizzo",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('204', () => pm.response.to.have.status(204));"
        ]
       }
      }
     ],
     "request": {
      "method": "DELETE",
      "header": [
       {
        "key": "Accept",
        "value": "application/json"
